<?php
require_once __DIR__.'/security.php';
function supported_languages(): array { return ['en'=>['flag'=>'/assets/img/flags/gb.svg','code'=>'GB','name'=>'English'],'tr'=>['flag'=>'/assets/img/flags/tr.svg','code'=>'TR','name'=>'Türkçe'],'ru'=>['flag'=>'/assets/img/flags/ru.svg','code'=>'RU','name'=>'Русский'],'es'=>['flag'=>'/assets/img/flags/es.svg','code'=>'ES','name'=>'Español'],'de'=>['flag'=>'/assets/img/flags/de.svg','code'=>'DE','name'=>'Deutsch']]; }
function current_language(): string { static $code=null;if($code!==null)return $code;$supported=supported_languages();$requested=strtolower($_GET['lang']??'');if(isset($supported[$requested])){$code=$requested;setcookie('imgtr_lang',$code,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>false,'samesite'=>'Lax']);return $code;}$saved=strtolower($_COOKIE['imgtr_lang']??'');if(isset($supported[$saved]))return $code=$saved;$country=strtoupper($_SERVER['HTTP_CF_IPCOUNTRY']??'');$countryMap=['TR'=>'tr','RU'=>'ru','BY'=>'ru','KZ'=>'ru','ES'=>'es','MX'=>'es','AR'=>'es','CO'=>'es','CL'=>'es','PE'=>'es','VE'=>'es','DE'=>'de','AT'=>'de','CH'=>'de'];if(isset($countryMap[$country]))return $code=$countryMap[$country];$header=strtolower($_SERVER['HTTP_ACCEPT_LANGUAGE']??'');foreach(explode(',',$header) as $part){$candidate=substr(trim(explode(';',$part)[0]),0,2);if(isset($supported[$candidate]))return $code=$candidate;}return $code='en'; }
function language(): array { static $cache=[];$code=current_language();if(!isset($cache[$code])){$english=require __DIR__.'/../languages/en.php';$local=$code==='en'?[]:require __DIR__.'/../languages/'.$code.'.php';$extra=require __DIR__.'/translations-extra.php';$album=require __DIR__.'/translations-album.php';$marketing=require __DIR__.'/translations-marketing.php';$zero=require __DIR__.'/translations-zero-storage.php';$exif=require __DIR__.'/translations-exif.php';$policy=require __DIR__.'/translations-policy.php';$consistency=require __DIR__.'/translations-consistency.php';$relay=require __DIR__.'/translations-relay.php';$share=require __DIR__.'/translations-share.php';$deletion=require __DIR__.'/translations-deletion.php';$developer=require __DIR__.'/translations-developer.php';$status=require __DIR__.'/translations-status.php';$sharex=require __DIR__.'/translations-sharex.php';$seo=require __DIR__.'/translations-seo.php';$control=require __DIR__.'/translations-control.php';$legal=require __DIR__.'/translations-legal-current.php';$legalUi=require __DIR__.'/translations-legal-ui.php';$cache[$code]=array_replace($english,$extra['en']??[],$album['en']??[],$marketing['en']??[],$zero['en']??[],$exif['en']??[],$policy['en']??[],$consistency['en']??[],$relay['en']??[],$share['en']??[],$deletion['en']??[],$developer['en']??[],$status['en']??[],$sharex['en']??[],$seo['en']??[],$control['en']??[],$legal['en']??[],$legalUi['en']??[],$local,$extra[$code]??[],$album[$code]??[],$marketing[$code]??[],$zero[$code]??[],$exif[$code]??[],$policy[$code]??[],$consistency[$code]??[],$relay[$code]??[],$share[$code]??[],$deletion[$code]??[],$developer[$code]??[],$status[$code]??[],$sharex[$code]??[],$seo[$code]??[],$control[$code]??[],$legal[$code]??[],$legalUi[$code]??[]);}return $cache[$code]; }
function t(string $key,array $replace=[]): string {if($key==='network'){$networkCopy=['en'=>'Powered by independent distributed storage locations.','tr'=>'Bağımsız dağıtık depolama noktalarıyla çalışır.','ru'=>'Работает на независимых распределённых хранилищах.','es'=>'Funciona con ubicaciones de almacenamiento distribuidas e independientes.','de'=>'Unterstützt durch unabhängige verteilte Speicherorte.'];$value=$networkCopy[current_language()]??$networkCopy['en'];}else{$value=language()[$key]??$key;}foreach($replace as $name=>$replacement)$value=str_replace('{'.$name.'}',(string)$replacement,$value);return $value;}
function language_picker(): void {$current=current_language();$languages=supported_languages();$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';?><details class="language-picker"><summary aria-label="<?=e(t('language'))?>"><img src="<?=e($languages[$current]['flag'])?>" alt=""><b><?=e($languages[$current]['code'])?></b></summary><div><?php foreach($languages as $code=>$item):?><a href="<?=e($path.'?lang='.$code)?>" class="<?=$code===$current?'active':''?>"><img src="<?=e($item['flag'])?>" alt=""><span><?=e($item['name'])?></span></a><?php endforeach?></div></details><?php }
